const MAX_RECORD_BYTES = 16 * 1024 * 1024;
const fileInfo = await media.info(inputs.record_file);
if (fileInfo.size > MAX_RECORD_BYTES) throw new Error("The campaign record exceeds the 16 MiB portable record limit.");
if (fileInfo.mimeType !== "application/json") throw new Error(`Campaign record MIME type must be application/json, received ${fileInfo.mimeType || "unknown"}.`);
let record;
try { record = JSON.parse(await media.text(inputs.record_file)); } catch { throw new Error("The campaign record contains malformed JSON. The current campaign was not changed."); }
if (!record || record.schemaVersion !== 1) throw new Error("Campaign record schemaVersion must be 1. The current campaign was not changed.");
if (!["original", "revision"].includes(record.acceptedVersion)) throw new Error("Campaign record acceptedVersion must be original or revision.");
const text = (label, value, max) => {
  if (typeof value !== "string" || value.length === 0) throw new Error(`${label} is required.`);
  if (value.length > max) throw new Error(`${label} exceeds ${max} characters.`);
  return value;
};
if (!record.brief || typeof record.brief !== "object") throw new Error("Campaign record brief is missing.");
text("Product name", record.brief.productName, 120);
text("Campaign message", record.brief.campaignMessage, 600);
text("Audience", record.brief.audience, 300);
text("Headline", record.brief.headline, 120);
text("CTA", record.brief.cta, 80);
const roles = ["none", "composition", "palette", "material", "lighting"];
if (!record.references || !roles.includes(record.references.role)) throw new Error("Campaign record reference role is invalid.");
if (String(record.references.use ?? "").length > 300 || String(record.references.ignore ?? "").length > 300) throw new Error("Campaign record reference notes exceed 300 characters.");
const directionFields = ["id", "title", "setting", "composition", "lighting", "palette", "preservationInstructions"];
if (!record.selectedDirection || record.selectedDirection.id === undefined) throw new Error("Campaign record selected direction is missing.");
if (!["A", "B", "C"].includes(record.selectedDirection.id)) throw new Error("Campaign record selected direction ID is invalid.");
for (const field of directionFields) text(`Selected direction ${field}`, record.selectedDirection[field], field === "id" ? 1 : 600);
if (!record.approvedCopy || record.approvedCopy.productName !== record.brief.productName || record.approvedCopy.headline !== record.brief.headline || record.approvedCopy.cta !== record.brief.cta) throw new Error("Campaign record approved copy does not match its brief.");
const validateContract = (contract, kind, label) => {
  if (!contract || contract.schemaVersion !== 1 || contract.kind !== kind || !contract.brief || !contract.copy || !contract.selectedDirection) throw new Error(`${label} is incomplete.`);
  if (contract.copy.productName !== record.approvedCopy.productName || contract.copy.headline !== record.approvedCopy.headline || contract.copy.cta !== record.approvedCopy.cta) throw new Error(`${label} copy does not match the approved copy.`);
};
if (!record.original || typeof record.original !== "object") throw new Error("Campaign record original section is missing.");
validateContract(record.original.contract, "hero", "Original contract");
if (record.acceptedVersion === "revision") {
  if (!record.revision || typeof record.revision !== "object") throw new Error("A revision record must include the revision section.");
  validateContract(record.revision.contract, "revision", "Revision contract");
  if (JSON.stringify(record.revision.contract.parentContract) !== JSON.stringify(record.original.contract)) throw new Error("Revision ancestry does not match the accepted original contract.");
  if (!record.revision.request || JSON.stringify(record.revision.request) !== JSON.stringify(record.revision.contract.revisionRequest)) throw new Error("Revision request does not match the revision contract.");
  text("Revision change", record.revision.request.change, 500);
  text("Revision preserve", record.revision.request.preserve, 700);
  text("Revision allow", record.revision.request.allow, 500);
} else if (record.revision !== undefined && record.revision !== null) {
  throw new Error("An original-only record cannot contain an accepted revision.");
}
await output("gate", "validated");

if (String(inputs.gate ?? "") !== "validated") return;
let record;
try { record = JSON.parse(await media.text(inputs.record_file)); } catch { throw new Error("The campaign record could not be reread during media validation."); }
const item = record.original?.source;
if (!item && "original" === "revision" && record.acceptedVersion === "original") {
  await output("gate", "validate-original-source");
} else {
  if (!item || typeof item !== "object") throw new Error("original source is missing.");
  const allowed = "source" === "svg" ? ["image/svg+xml"] : "source" === "png" ? ["image/png"] : ["image/png", "image/jpeg", "image/webp", "image/avif"];
  if (!allowed.includes(item.mimeType)) throw new Error(`original source has unsupported MIME type ${item.mimeType || "unknown"}.`);
  const width = null;
  const height = null;
  if (width !== null && (item.width !== width || item.height !== height)) throw new Error(`original source must be exactly ${width}×${height}.`);
  if (width === null && (!Number.isInteger(item.width) || !Number.isInteger(item.height) || item.width < 1 || item.height < 1 || item.width > 4096 || item.height > 4096)) throw new Error("original source has invalid source dimensions.");
  if (typeof item.data !== "string" || item.data.length === 0 || item.data.length % 4 !== 0 || !/^[A-Za-z0-9+/]*={0,2}$/.test(item.data)) throw new Error("original source has invalid base64 data.");
  const bytes = fromBase64(item.data);
  if (bytes.length === 0 || toBase64(bytes) !== item.data) throw new Error("original source has invalid base64 data.");
  await output("gate", "validate-original-source");
}

